BOUNDS_MAX = (9.40000057220459, 5, 0.59422367811203)

def ensure_collection(name):
    collection = bpy.data.collections.get(name)
    if collection is None:
        collection = bpy.data.collections.new(name)
        bpy.context.scene.collection.children.link(collection)
    return collection

def remove_existing_object(name):
    obj = bpy.data.objects.get(name)
    if obj is not None:
        bpy.data.objects.remove(obj, do_unlink=True)

def keyframe_prop(obj, key, value, frame):
    obj[key] = value
    obj.keyframe_insert(data_path=f'["{key}"]', frame=frame)

def create_bounds_object(name, bounds_min, bounds_max, collection):
    if bounds_min is None or bounds_max is None:
        return None
    min_x, min_y, min_z = bounds_min
    max_x, max_y, max_z = bounds_max
    verts = [
        (min_x, min_y, min_z),
        (max_x, min_y, min_z),
        (max_x, max_y, min_z),
        (min_x, max_y, min_z),
        (min_x, min_y, max_z),
        (max_x, min_y, max_z),
        (max_x, max_y, max_z),
        (min_x, max_y, max_z),
    ]
    edges = [
        (0, 1), (1, 2), (2, 3), (3, 0),
        (4, 5), (5, 6), (6, 7), (7, 4),
        (0, 4), (1, 5), (2, 6), (3, 7),
    ]
    mesh = bpy.data.meshes.new(name)
    mesh.from_pydata(verts, edges, [])
    mesh.update()
    obj = bpy.data.objects.new(name, mesh)
    obj.display_type = 'WIRE'
    obj.hide_render = True
    collection.objects.link(obj)
    return obj

collection = ensure_collection(COLLECTION_NAME)
remove_existing_object(CAMERA_NAME)
remove_existing_object(RIG_NAME)
remove_existing_object(BOUNDS_NAME)
rig = bpy.data.objects.new(RIG_NAME, None)
